from typing import Optional

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class EventsMethods(BaseClient):
    """
    Методы группы 'События' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=65)
    @tracer.start_as_current_span("events.rapi_events_poll")
    def rapi_events_poll(self, pollTime: int, lastEventId: Optional[int] = None):
        """
        Получение событий для webapp сессий.

        Необходима подписка через /rapi/eventSubscribe
        :param lastEventId: id последнего известного события
        :param pollTime: таймаут в секундах на выполнение long polling
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/events/poll",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "lastEventId": lastEventId or self.lastEventId,
                    "pollTime": pollTime,
                },
            },
        )

    @api_version_check(min_version=4)
    @tracer.start_as_current_span("events.rapi_eventSubscribe")
    def rapi_eventSubscribe(self, subscriptions: list[dict]) -> dict:
        """
        Универсальный метод подписок на события
        :param subscriptions: Массив подписок на различные типы событий
        :return: тело ответа сервера
        """
        try:
            try:
                return self.post(
                    "rapi/eventSubscribe",
                    headers={"Content-Type": "application/json"},
                    json={
                        "aimsid": self.aimsid,
                        "reqId": self.getReqId(),
                        "params": {"subscriptions": subscriptions},
                    },
                )
            except Exception as error:
                self.logger.exception(error)
                return self.request(
                    method="POST",
                    url="/".join([self.api_url, "api", "v92", "rapi/eventSubscribe"]),
                    headers={"Content-Type": "application/json"},
                    json={
                        "aimsid": self.aimsid,
                        "reqId": self.getReqId(),
                        "params": {"subscriptions": subscriptions},
                    },
                )
        except Exception as error:
            message, *args = error.args
            error.args = (
                ":".join(
                    message.split(":")[:2]
                    + [x["type"] for x in (subscriptions if isinstance(subscriptions, list) else [subscriptions])]
                    + message.split(":")[2:],
                ),
            )
            raise error
